// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0);
        vm.deal(address(c), amount);
        address owner = c.owner();
        uint256 beforeBal = owner.balance;
        vm.prank(owner);
        bool ok = true;
        try c.withdraw(amount) { ok = true; } catch { ok = false; }
        if (ok) {
            assertEq(owner.balance, beforeBal + amount);
        }
    }
}
